"""Generate Rust and web contracts from the Python multi-server protocol owner."""
from __future__ import annotations

import argparse
import sys

from codex_layout import REPOSITORY_ROOT
from codex_multi_server_protocol import (
    ACCESS_PROTOCOL_VERSION,
    MULTI_SERVER_SIGNING_DOMAIN,
)


RUST_OUTPUT = (
    REPOSITORY_ROOT
    / "workspaces/runtime/packages/runtime-services/src/multi_server_protocol_generated.rs"
)
WEB_OUTPUT = (
    REPOSITORY_ROOT
    / "workspaces/client/apps/web/src/generated/multiServerProtocol.ts"
)
RUST_EXPECTED = (
    "//! Generated by `studio_api.generate_multi_server_protocol`; do not edit.\n"
    "//! Source: `codex_multi_server_protocol.py`.\n"
    f"pub const ACCESS_PROTOCOL_VERSION: u64 = {ACCESS_PROTOCOL_VERSION};\n"
    f'pub const MULTI_SERVER_SIGNING_DOMAIN: &str = "{MULTI_SERVER_SIGNING_DOMAIN}";\n'
)
WEB_EXPECTED = (
    "// Generated by studio_api.generate_multi_server_protocol; do not edit.\n"
    "// Source: codex_multi_server_protocol.py.\n"
    f"export const ACCESS_PROTOCOL_VERSION = {ACCESS_PROTOCOL_VERSION} as const;\n"
    f'export const MULTI_SERVER_SIGNING_DOMAIN = "{MULTI_SERVER_SIGNING_DOMAIN}" as const;\n'
)
OUTPUTS = {RUST_OUTPUT: RUST_EXPECTED, WEB_OUTPUT: WEB_EXPECTED}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true", help="write generated protocol contracts")
    mode.add_argument("--check", action="store_true", help="check generated protocol contracts")
    args = parser.parse_args(argv)
    for path, expected in OUTPUTS.items():
        if args.check:
            try:
                current = path.read_text(encoding="utf-8")
            except (OSError, UnicodeError):
                current = None
            if current != expected:
                print(
                    f"{path.relative_to(REPOSITORY_ROOT)} is stale; "
                    "run `pnpm run multi-server-protocol:generate`",
                    file=sys.stderr,
                )
                return 1
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
